<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {useArcade} from '../stores/arcade'
import {useLearning} from '../stores/learning'
import {useMessages} from '../stores/messages'
import DailyNotes from '../components/DailyNotes.vue'
import GameHeader from '../components/GameHeader.vue'
import CharacterPicker from '../components/CharacterPicker.vue'
import PartnerImage from '../components/PartnerImage.vue'
import PixelDecor from '../components/PixelDecor.vue'
import ItemSlotWindow from '../components/ItemSlotWindow.vue'
const notesOpen=ref(false);const messages=useMessages(),learning=useLearning();onMounted(()=>learning.load());const s=useArcade();s.age();const p=computed(()=>s.data.pet);const message=ref('파트너와 행복한 하루를 보내요!');const started=ref(false)
import {items} from '../data/items'
const heartBurst=ref(false),heartKey=ref(0);let heartTimer;onUnmounted(()=>clearTimeout(heartTimer));
async function care(type){try{await s.petAction(type==='food'?'food':'play');heartKey.value++;heartBurst.value=true;clearTimeout(heartTimer);heartTimer=setTimeout(()=>heartBurst.value=false,1600);message.value='파트너가 기뻐해요!'}catch(e){message.value=e.message}}
</script>
<template><GameHeader tag="03 / MY LITTLE FRIEND" title="마이 리틀 펫" description="먹이(10코인)와 놀이(5코인)로 경험치를 모아요. 100경험치마다 레벨 업! 포만감과 행복은 시간에 따라 천천히 줄어듭니다."/><div class="pet-study-menu"><button class="light" @click="notesOpen=true">✎ 오늘 배운 내용 정리하기</button><RouterLink to="/workshop" class="button light">문제 제작소 →</RouterLink><RouterLink to="/pet" class="button light">파트너 돌보기</RouterLink><RouterLink to="/pet/mistakes" class="button light">틀린 문제! <b>{{learning.pendingCount}}</b> →</RouterLink><RouterLink to="/pet/mailbox" class="button light">✉ 내 쪽지함 <b v-if="messages.unread" class="unread-badge">{{messages.unread}}</b></RouterLink></div><div class="friendship-banner"><PixelDecor kind="hearts"/><div><p class="eyebrow">LITTLE FRIEND, BIG HEART</p><h3>오늘도 함께 자라는 중!</h3></div><PixelDecor kind="clover"/></div><section class="panel partner-select-panel"><div class="partner-select-heading"><p class="eyebrow">MY FOREVER PARTNER</p><h2>우리의 모험은 여기서 시작!</h2></div><CharacterPicker :model-value="s.partner.id" :locked="s.data.partnerLocked" @update:model-value="s.selectCharacter"/></section><div v-if="!started" class="panel empty"><PartnerImage size="large"/><h2>{{s.partner.name}}와 함께 놀까요?</h2><p>성장은 자동 저장되며 다시 만날 때도 이어집니다.</p><button @click="started=true">만나기 시작</button></div><div v-else class="pet-layout"><div class="panel"><div class="pet-scene"><div v-if="heartBurst" :key="heartKey" class="care-heart-burst" aria-hidden="true"><span v-for="i in 8" :key="i" :style="{'--heart-i':i}">♥</span></div><span class="cloud">☁</span><span class="hat">{{p.wear}}</span><PartnerImage size="scene"/><span class="grass">🌼 🌱 🌷</span><PixelDecor kind="hearts" class="pet-scene-hearts"/></div><h2 class="center">{{s.partner.name}} <span class="level">Lv.{{s.level}}</span></h2><p class="center" role="status">{{message}}</p><div class="pet-meters"><label>포만감 <b>{{Math.round(p.hunger)}} / 100</b><progress :value="p.hunger" max="100"/></label><label>행복 <b>{{Math.round(p.happy)}} / 100</b><progress :value="p.happy" max="100"/></label><label>경험치 <b>{{p.xp%100}} / 100</b><progress :value="p.xp%100" max="100"/></label></div><div class="toolbar"><button @click="care('food')">🍎 먹이 주기 · 10 🪙</button><button @click="care('play')">🎾 놀아주기 · 5 🪙</button></div><button class="text-button" @click="started=false;message='다시 만나서 반가워요!'">↻ 돌보기 재시작 (성장 유지)</button></div><ItemSlotWindow :items="items"/></div><DailyNotes v-if="notesOpen" @close="notesOpen=false"/></template>
